def random_search(n, target_edges, min_girth, k_colors, num_trials=200):
    best = []

    for trial in range(num_trials):
        all_edges = [(u,v) for u in range(n) for v in range(u+1,n)]
        random.shuffle(all_edges)

        edges = []
        adj = [set() for _ in range(n)]

        for u, v in all_edges:
            sp = shortest_path_len(adj, u, v, n)
            if sp >= min_girth - 1:
                edges.append((u,v))
                adj[u].add(v)
                adj[v].add(u)

        if len(edges) > len(best):
            best = edges[:]
